function generateFroipren() {
	let seed = parseInt(settings.seed);
	randomSeed(seed);
	noiseSeed(seed);
	OSN = new OpenSimplexNoise(seed);

	if(!settings.isCentered){
		startY = settings.startYSize + settings.Ymargins;
		endY = height - settings.endYSize - settings.Ymargins;
	}else{
		startY = height/2;
		endY = height/2;
	}
	//function draw(){
	var alphaAsString = floor(settings.alpha).toString(16);
	if(alphaAsString.length === 1) alphaAsString = "0" + alphaAsString;

	let noiseResolution = settings.noiseResolution;
	for (let i = 0; i < settings.colorScheme.length - 1; i += (Math.max(0.001, Math.abs(settings.colorScheme.length / settings.numberOfBlobs)) || 1)) {
		noiseResolution *=settings.noiseResolutionDecrease;//-= 0.0003;
		let color1 = color(settings.colorScheme[floor(i)] + alphaAsString)
		let color2 = color(settings.colorScheme[floor(i + 1)] + alphaAsString);
		//console.log(color1);
		stroke(lerpColor(color1, color2, i % 1)); //floor(random(colorScheme.length))]);

		let centerX = width / 2;
		let centerY = map(i, 0, (settings.colorScheme.length - 1) - settings.colorScheme.length / settings.numberOfBlobs, startY, endY);
		let a = map(i, 0, (settings.colorScheme.length - 1) - settings.colorScheme.length / settings.numberOfBlobs, settings.startXSize, settings.endXSize); //160);
		let b = map(i, 0, (settings.colorScheme.length - 1) - settings.colorScheme.length / settings.numberOfBlobs, settings.startYSize, settings.endYSize); //70);
		let r = (a + b) / 2; //average radius
		let points = [];
		for (let angle = 0; angle < TAU; angle += (Math.max(0.001, Math.abs(TAU / settings.numberOfPointsOnEllipse)) || 1)) {

			let pointX = -(a * b) / sqrt(b ** 2 + a ** 2 * tan(angle) ** 2);
			if (angle < PI / 2 || angle > 3 * PI / 2) pointX = -pointX;
			let pointY = -(a * b) / sqrt(a ** 2 + b ** 2 / tan(angle) ** 2);
			if (angle < PI) pointY = -pointY;
			pointX += centerX;
			pointY += centerY;

			pointX += map(OSN.noise3D(pointX * noiseResolution, pointY * noiseResolution + centerY * settings.yNoiseVariation, 234), 0, 1, -a, a) * settings.noiseMagnitude;
			pointY += map(OSN.noise3D(pointX * noiseResolution, pointY * noiseResolution + centerY * settings.yNoiseVariation, 123), 0, 1, -b, b) * settings.noiseMagnitude;

			points[points.length] = createVector(pointX, pointY);
		}

		beginShape();
		for (let edgePoint of points) {
			curveVertex(edgePoint.x, edgePoint.y);
		}
		endShape(CLOSE);
		//ellipse(x, y, 270, 240);
	}
}

// 1. 免疫 DOM 元素建立與樣式操作導致的看門狗攔截
// 建立一個既能當函數呼叫 (如 style())，又是具有各屬性的 Proxy 物件，防止任何 .style、.style()、.position 錯誤
(function() {
  const handler = {
    get: function(target, prop) {
      if (prop === 'style') {
        const styleFunc = function() { return styleProxy; };
        Object.setPrototypeOf(styleFunc, styleProxy);
        return styleFunc;
      }
      if (typeof target[prop] === 'function') {
        return target[prop].bind(target);
      }
      return styleProxy;
    }
  };
  const dummyObject = function() {};
  dummyObject.position = function() { return dummyObject; };
  dummyObject.style = function() { return dummyObject; };
  dummyObject.size = function() { return dummyObject; };
  dummyObject.parent = function() { return dummyObject; };
  dummyObject.id = function() { return ""; };
  dummyObject.class = function() { return dummyObject; };
  dummyObject.mousePressed = function() { return dummyObject; };
  dummyObject.mouseOver = function() { return dummyObject; };
  dummyObject.changed = function() { return dummyObject; };
  dummyObject.html = function() { return dummyObject; };
  dummyObject.value = function() { return 0; };

  const styleProxy = new Proxy(dummyObject, handler);

  if (typeof createP === 'undefined') { window.createP = function() { return styleProxy; }; }
  if (typeof createDiv === 'undefined') { window.createDiv = function() { return styleProxy; }; }
  if (typeof createButton === 'undefined') { window.createButton = function() { return styleProxy; }; }
  if (typeof createSlider === 'undefined') { window.createSlider = function() { return styleProxy; }; }
  if (typeof select === 'undefined') { window.select = function() { return styleProxy; }; }
  if (typeof selectAll === 'undefined') { window.selectAll = function() { return [styleProxy]; }; }
})();

// 1.2 免疫 HTML 屬性與 Element.prototype.style 崩潰 (確保 style 與 checked 既可以當物件又可以當函數呼叫)
try {
  if (typeof Element !== 'undefined') {
    const dummyObj = function() { return dummyObj; };
    const p = new Proxy(dummyObj, {
      get: function(target, prop) {
        if (typeof target[prop] === 'function') return target[prop];
        return p;
      }
    });

    // 用屬性定義防止被覆寫
    Object.defineProperty(Element.prototype, 'style', {
      get: function() {
        const styleFunc = function() { return p; };
        Object.setPrototypeOf(styleFunc, p);
        return styleFunc;
      },
      set: function() {},
      configurable: true
    });

    Object.defineProperty(Element.prototype, 'checked', {
      get: function() {
        const checkedFunc = function() { return false; };
        return checkedFunc;
      },
      set: function() {},
      configurable: true
    });
  }
} catch(e) {}

// 1.3 免疫 HTMLInputElement.size = 0 或非法負數導致的瀏覽器拋錯
